import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent's past defections and recent behavior
    opp_defects = 0
    my_defects = 0
    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    # Detect if opponent is highly cooperative
    if opp_defects == 0:
        # Cooperate unless it's the very last round
        if n == 100:
            return 'D'
        return 'C'

    # Opponent has defected at least once. Use a forgiving tit-for-tat variant
    # with a probabilistic cooperative probe to escape mutual defection traps.

    # If opponent defected heavily, punish more
    defect_rate = opp_defects / n

    # Last few moves
    last_me, last_op = history[-1]

    # If opponent just defected, respond with defection most of the time,
    # but sometimes cooperate to probe for recovery.
    if last_op == 'D':
        if defect_rate > 0.6:
            # Mostly defect against chronic defectors, occasional probe
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        else:
            # Reciprocal punishment with occasional forgiveness
            if rng.random() < 0.25:
                return 'C'
            return 'D'

    # Opponent just cooperated
    if last_op == 'C':
        # If they've been mostly cooperative, cooperate
        if defect_rate < 0.3:
            if n == 100:
                return 'D'
            return 'C'
        # If they've been mixed, cooperate but watch
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    return 'C'
